/* 独立题集和知识卡片只共享本地复习记录，不更改题库内容。 */
window.GISStudy=(()=>{const KEY='gis-study-records-v1';function read(){try{const x=JSON.parse(localStorage.getItem(KEY)||'{}');return {version:1,cards:x.cards&&typeof x.cards==='object'&&!Array.isArray(x.cards)?x.cards:{},wrong:x.wrong&&typeof x.wrong==='object'&&!Array.isArray(x.wrong)?x.wrong:{}}}catch{return {version:1,cards:{},wrong:{}}}}function write(x){localStorage.setItem(KEY,JSON.stringify(x))}function exportData(){const data={format:'gis-study-backup',version:1,records:read(),chapters:localStorage.getItem('gis-study-done')};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='gis-study-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}async function importData(file){if(!file||file.size>2e6)throw Error('文件为空或超过 2 MB');const d=JSON.parse(await file.text());if(d.format!=='gis-study-backup'||d.version!==1||!d.records||typeof d.records.cards!=='object'||Array.isArray(d.records.cards)||typeof d.records.wrong!=='object'||Array.isArray(d.records.wrong))throw Error('文件格式不正确');const chapter=d.chapters===null?null:JSON.parse(d.chapters);if(chapter!==null&&(!Array.isArray(chapter)||chapter.some(n=>!Number.isInteger(n)||n<1||n>11)))throw Error('章节进度格式有误');const cards={};for(const [k,v] of Object.entries(d.records.cards)){if(typeof k!=='string'||!v||!['unknown','fuzzy','known'].includes(v.level)||!Number.isFinite(v.due))throw Error('卡片记录格式有误');cards[k]={level:v.level,due:v.due}}const wrong={};for(const [k,v] of Object.entries(d.records.wrong)){if(!/^\d+-\d+$/.test(k)||v!==true)throw Error('错题记录格式有误');wrong[k]=true}if(!confirm('导入会替换当前浏览器的卡片状态、错题及章节进度。建议先导出备份。确定继续吗？'))return false;write({version:1,cards,wrong});if(chapter===null)localStorage.removeItem('gis-study-done');else localStorage.setItem('gis-study-done',JSON.stringify(chapter));return true}return{read,write,exportData,importData}})();
